  name: "Phone — the thread is gone",
  parameters: phoneParams,
  decorators: [phoneFrame],
  render: () => <CalendarAgenda width={PHONE_WIDTH} date="2026-06-10" flow="event" selectedEventId="evt_q3_roadmap" openThreadId="thr_filed_away" />,
